CREATE SEQUENCE IF NOT EXISTS tracking_sequence;
CREATE TABLE vendors(id text PRIMARY KEY,name text NOT NULL,pan text NOT NULL,gstin text NOT NULL,bank_hash text NOT NULL,status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cases(id text PRIMARY KEY,tracking_id text NOT NULL UNIQUE,vendor_id text REFERENCES vendors(id),owner_id text NOT NULL,idempotency_key text NOT NULL UNIQUE,status text NOT NULL,pending_owner text,current_revision integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE revisions(id text PRIMARY KEY,case_id text NOT NULL REFERENCES cases(id),number integer NOT NULL,submitted_values jsonb NOT NULL,policy_version text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(case_id,number));
CREATE TABLE documents(id text PRIMARY KEY,revision_id text NOT NULL REFERENCES revisions(id),slot text NOT NULL,filename text NOT NULL,sha256 text NOT NULL,bytes_base64 text NOT NULL,detected_type text,extracted_json jsonb,confidence text,source text,provenance text,error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE runs(id text PRIMARY KEY,revision_id text NOT NULL REFERENCES revisions(id),state text NOT NULL,stages jsonb NOT NULL DEFAULT '[]',error text,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE check_results(id text PRIMARY KEY,run_id text NOT NULL REFERENCES runs(id),data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE decisions(id text PRIMARY KEY,revision_id text NOT NULL REFERENCES revisions(id),run_id text NOT NULL REFERENCES runs(id),data jsonb NOT NULL,source text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events(id text PRIMARY KEY,case_id text NOT NULL REFERENCES cases(id),actor text NOT NULL,actor_type text NOT NULL,action text NOT NULL,previous_state text,new_state text,note text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE blocklist(id text PRIMARY KEY,identifier text NOT NULL,type text NOT NULL,reason text NOT NULL,active boolean NOT NULL DEFAULT true,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE extraction_cache(key text PRIMARY KEY,sha256 text NOT NULL,extractor_version text NOT NULL,schema_version text NOT NULL,evidence jsonb NOT NULL,provenance text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX cases_owner ON cases(owner_id);
CREATE INDEX revisions_case ON revisions(case_id);
CREATE INDEX documents_revision ON documents(revision_id);
CREATE INDEX runs_revision ON runs(revision_id);
CREATE INDEX checks_run ON check_results(run_id);
CREATE INDEX audits_case ON audit_events(case_id);
CREATE INDEX vendors_bank ON vendors(bank_hash);
CREATE FUNCTION protect_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit events are append-only'; END $$;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION protect_audit();
